require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/CeoDashboardExcel.php';require_once __DIR__.'/../lib/PayrollImportService.php';if(!PayrollRepository::canImport()){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='ایمپورت حقوق و دستمزد';$adminExtraStylesheets=['/assets/css/workforce.css'];$periodId=(int)($_GET['period_id']??$_POST['period_id']??0);if(($_GET['action']??'')==='template'){$period=Database::fetch('SELECT * FROM payroll_periods WHERE id=?',[$periodId]);if(!$period){http_response_code(404);exit('دوره معتبر نیست.');}$rows=PayrollImportService::templateRows();$rows[1][1]=$period['period_key'];CeoDashboardExcel::output(['حقوق و دستمزد'=>$rows],'payroll-'.$period['period_key'].'-template.xlsx');}
if(($_GET['action']??'')==='errors'){$batchId=(int)($_GET['batch_id']??0);$rows=Database::fetchAll("SELECT source_row,employee_no,error_message FROM payroll_import_rows WHERE batch_id=? AND status IN ('error','skipped') ORDER BY source_row",[$batchId]);header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="payroll-errors-'.$batchId.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['source_row','employee_no','error_message']);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}
