$periods=Database::fetchAll("SELECT * FROM payroll_periods WHERE status IN ('draft','imported') ORDER BY year DESC,month DESC");$batchId=(int)($_GET['batch_id']??0);$batch=$batchId?Database::fetch('SELECT b.*,p.title period_title FROM payroll_import_batches b JOIN payroll_periods p ON p.id=b.period_id WHERE b.id=?',[$batchId]):null;$preview=$batch?Database::fetchAll('SELECT * FROM payroll_import_rows WHERE batch_id=? ORDER BY source_row LIMIT 500',[$batchId]):[];$batches=Database::fetchAll('SELECT b.*,p.title period_title,u.name importer_name FROM payroll_import_batches b JOIN payroll_periods p ON p.id=b.period_id LEFT JOIN users u ON u.id=b.imported_by ORDER BY b.id DESC LIMIT 30');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>ایمپورت حقوق و دستمزد</h1><p>تطبیق امن بر اساس شماره پرسنلی و پیش‌نمایش قبل از ثبت</p></div><?php if($periodId):?><a class="btn" href="?action=template&period_id=<?=$periodId?>">دانلود قالب داینامیک</a><?php endif?></div><nav class="workforce-tabs"><a href="/admin/payroll-periods.php">دوره‌ها</a><a href="/admin/payroll-fields.php">فیلدها</a><a class="is-active" href="/admin/payroll-import.php">ایمپورت</a><a href="/admin/payroll-slips.php">فیش‌ها</a></nav><section class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="preview"><div class="compact-grid"><label class="form-field"><span>دوره حقوقی</span><select name="period_id" required><option value="">انتخاب کنید</option><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=$periodId===$p['id']?'selected':''?>><?=e($p['title'].' — '.$p['period_key'])?></option><?php endforeach?></select></label><label class="form-field"><span>فایل Excel/CSV</span><input type="file" name="excel_file" accept=".xlsx,.csv" required></label></div><button class="btn btn-primary">ساخت پیش‌نمایش</button></form></section><?php if($batch):?><section class="card"><div class="section-heading-row"><div><h2>پیش‌نمایش Batch #<?=$batch['id']?></h2><p class="muted"><?=e($batch['period_title'])?> — معتبر: <?=$batch['success_count']?>، خطا: <?=$batch['error_count']?></p></div><div class="form-actions"><a class="btn" href="?action=errors&batch_id=<?=$batch['id']?>">دانلود خطاها</a><?php if($batch['status']==='preview'):?><form method="post" onsubmit="return confirm('فقط ردیف‌های معتبر ثبت نهایی شوند؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="commit"><input type="hidden" name="period_id" value="<?=$batch['period_id']?>"><input type="hidden" name="batch_id" value="<?=$batch['id']?>"><button class="btn btn-primary">ثبت نهایی</button></form><?php endif?></div></div><div class="table-wrap"><table><thead><tr><th>ردیف</th><th>شماره پرسنلی</th><th>وضعیت</th><th>خطا</th></tr></thead><tbody><?php foreach($preview as $r):?><tr><td><?=$r['source_row']?></td><td><?=e($r['employee_no']?:'—')?></td><td><span class="workforce-status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['error_message']?:'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?><section class="card"><h2>تاریخچه Batchها</h2><div class="table-wrap"><table><thead><tr><th>Batch</th><th>دوره</th><th>فایل</th><th>موفق / خطا</th><th>وضعیت</th></tr></thead><tbody><?php foreach($batches as $b):?><tr><td><a href="?period_id=<?=$b['period_id']?>&batch_id=<?=$b['id']?>">#<?=$b['id']?></a></td><td><?=e($b['period_title'])?></td><td><?=e($b['file_name'])?></td><td><?=$b['success_count']?> / <?=$b['error_count']?></td><td><?=e($b['status'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
